return ['domain'=>'wpml-import','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'إضافة متعددة الأغراض لتصدير واستيراد المحتوى متعدد اللغات.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'لم يعد مشغل الاستيراد يقبل المفتاح في عنوان URL. أرسله في جسم POST.','Method Not Allowed'=>'الطريقة غير مسموح بها','Unauthorized'=>'غير مصرح له','No items to process'=>'لا توجد عناصر للمعالجة','No Content'=>'لا يوجد محتوى','Import process completed'=>'اكتملت عملية الاستيراد','Success'=>'نجاح','Import process failed'=>'فشلت عملية الاستيراد','Internal Server Error'=>'خطأ داخلي في الخادم','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: تعذر معالجة %2$d عنصرًا وتم تخطيها.' . "\0" . '%1$s: تعذّر معالجة %2$d عنصر وتم تخطيه.' . "\0" . '%1$s: تعذّر معالجة %2$d عنصرين وتم تخطيهما.' . "\0" . '%1$s: تعذّر معالجة %2$d عناصر وتم تخطيها.' . "\0" . '%1$s: تعذّر معالجة %2$d عنصرًا وتم تخطيه.' . "\0" . '%1$s: تعذّر معالجة %2$d عنصرًا وتم تخطيه.','Cleaning Up Post Data'=>'تنظيف بيانات المقالات','Removing temporary and import-related post meta data.'=>'إزالة البيانات الوصفية للمقالات المؤقتة والمتعلقة بالاستيراد.','Cleaning Up Term Data'=>'تنظيف بيانات العناصر','Removing temporary and import-related term meta data.'=>'إزالة البيانات الوصفية للعناصر المؤقتة والمتعلقة بالاستيراد.','Connecting Post Image Attachments'=>'ربط مرفقات صور المقالات','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'تحديث معرفات مرفقات الصور المصغرة والمعرض في المقالات والمنتجات وأنواع المقالات المخصصة المترجمة لتشير إلى نظيراتها المترجمة.','Connecting Inline Term Translations'=>'ربط ترجمات العناصر المضمنة','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'فحص المقالات التي تحتوي على عنصر تصنيف واحد من أجل تحديد وربط العناصر المعينة لهذه المقالات بترجماتها.','Deleting Obsolete Original Terms'=>'حذف العناصر الأصلية المهملة','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'إزالة العناصر الأصلية التي لم تعد هناك حاجة إليها بعد إنشاء تكرارات للعناصر التي تحمل الاسم نفسه. التأكد من عدم ربط أي مقالات بهذه العناصر الأصلية.','Duplicating Terms with Shared Names Across Languages'=>'تكرار العناصر ذات الأسماء المشتركة عبر اللغات','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'إنشاء تكرارات باللغة الصحيحة للعناصر التي تشترك في نفس الاسم عبر اللغات، ولكنها تنتمي إلى مقالات بلغات مختلفة.','Fixing Imported Post Slugs'=>'إصلاح الأسماء اللطيفة للمقالات المستوردة','Regenerating translated post slugs to prevent conflicts with the originals.'=>'إعادة إنشاء الأسماء اللطيفة للمقالات المترجمة لمنع التعارض مع الأصول.','Clearing Translations Cache'=>'مسح ذاكرة ترجمات التخزين المؤقت','Invalidating the persistent cache so it can be regenerated.'=>'إبطال ذاكرة التخزين المؤقت المستمرة حتى يمكن إعادة إنشائها.','Marking Parent Terms for Connection'=>'تحديد العناصر الأب للربط','Collecting parent terms to connect their translations in the next step.'=>'جمع العناصر الأب لربط ترجماتها في الخطوة التالية.','Connecting Posts with Correct Term Translations'=>'ربط المقالات بترجمات العناصر الصحيحة','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'التأكد من ربط المقالات بالعناصر باللغة الصحيحة، خاصة إذا كان لديك نفس أسماء العناصر عبر اللغات.','Sending Posts for Automatic Translation'=>'إرسال المقالات للترجمة التلقائية','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'إنشاء وظائف ترجمة تلقائية للمقالات التي تم وضع علامة عليها للترجمة التلقائية في البيانات المصدرة.','Setting Attachments\' Language'=>'تعيين لغة المرفقات','Assigning a language to imported attachments.'=>'تعيين لغة للمرفقات المستوردة.','Updating Final Post Status'=>'تحديث حالة المقالة النهائية','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'تعيين حالة المقالة بناءً على حقل "_wpml_import_after_process_post_status" من ملف الاستيراد (إذا تم توفيره).','Identifying Inline Term Languages'=>'تحديد لغات العناصر المضمنة','Identifying and setting the language of terms created during post imports.'=>'تحديد وتعيين لغة العناصر التي تم إنشاؤها أثناء استيراد المقالات.','Setting Posts’ Language'=>'تعيين لغة المقالات','Connecting posts to the default language and translations.'=>'ربط المقالات باللغة الافتراضية والترجمات.','Setting Terms’ Language'=>'تعيين لغة العناصر','Connecting taxonomy terms to the default (original) language and translations.'=>'ربط عناصر التصنيف باللغة الافتراضية (الأصلية) والترجمات.','Setting Parent Terms\' Language'=>'تعيين لغة العناصر الأب','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'تعيين اللغة لعناصر التصنيف الأب التي ليس لها لغة، بناءً على اللغة المعينة لأبنائها.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'هل تقوم بترحيل موقعك متعدد اللغات؟ تذكر أيضًا تثبيت %s على موقعك الجديد قبل استيراد محتواك حتى نتمكن من استعادة كافة الترجمات.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'هل تقوم بترحيل متجرك متعدد اللغات؟ باستخدام %1$s و %2$s يمكنك نقل محتواك المترجم إلى موقع جديد، بما في ذلك المنتجات المضافة، والمنتجات المرقاة، وسمات المنتجات.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'هل تقوم بترحيل متجرك متعدد اللغات؟ تذكر تثبيت %1$s و %2$s على موقعك الجديد قبل استيراد محتواك حتى نتمكن من استعادة كافة الترجمات.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'هل تتطلع إلى استيراد محتواك متعدد اللغات؟ تذكر تثبيت %s في موقعك الأصلي قبل تصدير محتواه حتى نتمكن من استيراد كافة الترجمات هنا.','Looking to import your multilingual content? Install %1$s on this site.'=>'هل تتطلع إلى استيراد محتواك متعدد اللغات؟ ثبّت %1$s على هذا الموقع.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'تذكر أيضًا تمكين %2$s و %3$s في متجرك الأصلي قبل تصدير محتواه حتى نتمكن من استيراد كافة الترجمات هنا.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'هل تتطلع إلى استيراد محتواك متعدد اللغات؟ تذكر تمكين %1$s و %2$s في متجرك الأصلي قبل تصدير محتواه حتى نتمكن من استيراد كافة الترجمات هنا.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'التبديل إلى كافة اللغات','Linking Product Attribute Translations'=>'ربط ترجمات سمات المنتج','Connecting product attributes to their translations based on associated product variations.'=>'ربط سمات المنتج بترجماتها بناءً على تنويعات المنتج المرتبطة.','Updating Related Products On Translations'=>'تحديث المنتجات ذات الصلة في الترجمات','Setting up-sells, cross-sells and grouped products references in the right language.'=>'إعداد مراجع المنتجات المرقاة، والمنتجات المضافة، والمنتجات المجمعة باللغة الصحيحة.','Importing Custom Attribute Labels'=>'استيراد تسميات السمات المخصصة','Importing labels for product-specific (custom) attributes from the exported data.'=>'استيراد تسميات السمات الخاصة بالمنتج (المخصصة) من البيانات المصدرة.','You are about to export all your products in all languages at once.'=>'أنت على وشك تصدير كافة منتجاتك بجميع اللغات في وقت واحد.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'تذكر تثبيت %1$s و %2$s على موقعك الجديد قبل استيراد محتواك حتى نتمكن من استعادة كافة الترجمات.','You are about to export your products in %s.'=>'أنت على وشك تصدير منتجاتك بـ %s.','Registering Product Attributes'=>'تسجيل سمات المنتج','Identifying and registering attributes created during product imports for translation.'=>'تحديد وتسجيل السمات التي تم إنشاؤها أثناء استيراد المنتجات للترجمة.','Identifying Product Attribute Languages'=>'تحديد لغات سمات المنتج','Identifying and setting the language of attributes created during product imports.'=>'تحديد وتعيين لغة السمات التي تم إنشاؤها أثناء استيراد المنتجات.','Export and Import'=>'التصدير والاستيراد','I’m using the built-in %s export/import tool'=>'أنا أستخدم أداة تصدير/استيراد %s المدمجة','I’m using %s plugin'=>'أنا أستخدم إضافة %s','(%1$d/%2$d items)'=>'(%1$d/%2$d عنصرًا)','%d skipped'=>'تم تخطي %d','(no items)'=>'(لا توجد عناصر)','Counting items...'=>'جاري عد العناصر...','First, tell us how you’re going to create the content that you’ll be importing:'=>'أولاً، أخبرنا كيف ستقوم بإنشاء المحتوى الذي ستستورده:','Continue'=>'استمرار','I’m using %1$s and %2$s plugins'=>'أنا أستخدم إضافتي %1$s و %2$s','I’m using a different method to export from this site'=>'أنا أستخدم طريقة مختلفة للتصدير من هذا الموقع','I’m exporting the content from this site'=>'أنا أقوم بتصدير المحتوى من هذا الموقع','I’m exporting the content from a different website or system'=>'أنا أقوم بتصدير المحتوى من موقع ويب أو نظام مختلف','Before importing, add language columns to your content'=>'قبل الاستيراد، أضف أعمدة اللغة إلى محتواك','Make sure that your import file includes the following columns (custom fields) with language information:'=>'تأكد من أن ملف الاستيراد الخاص بك يتضمن الأعمدة التالية (الحقول المخصصة) مع معلومات اللغة:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: قيمة هي نفسها لكافة ترجمات كل عنصر. في مواقع التجارة الإلكترونية، غالبًا ما تكون هذه القيمة هي وحدة حفظ المخزون (SKU).','%s: The language code for each item.'=>'%s: رمز اللغة لكل عنصر.','And, you can include these two columns if needed:'=>'ويمكنك تضمين هذين العمودين إذا لزم الأمر:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: إذا كان هذا العنصر ترجمة، فقم بتعيين هذا العمود على رمز اللغة المصدر. إذا لم يكن ترجمة، فاتركه فارغًا.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: قم بالتعيين على ”مسودة“ أو ”منشور“ لتحديد حالة نشر المقالة بعد ضبط اللغات. عادةً ما تكون هذه القيمة ”منشور“.','Here is an example of importing two items, into your site’s languages (%s):'=>'إليك مثال على استيراد عنصرين إلى لغات موقعك (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'بمجرد إضافة أعمدة اللغة إلى ملف المحتوى متعدد اللغات الخاص بك، قم باستيراده إلى موقعك باستخدام أي إضافة استيراد تفضلها.','Before importing, your content needs language information'=>'قبل الاستيراد، يحتاج محتواك إلى معلومات اللغة','%s will add the necessary language information to your export.'=>'سيقوم %s بإضافة معلومات اللغة اللازمة إلى التصدير الخاص بك.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'قم باستيراد ملف المحتوى متعدد اللغات الخاص بك إلى الموقع باستخدام أي إضافة استيراد تفضلها.','Use your favorite import plugin'=>'استخدم إضافة الاستيراد المفضلة لديك','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'بعد استيراد المحتوى، لن تظهر معلومات اللغة الصحيحة بعد. لذا، نوصي باستيراد المحتوى الجديد كمسودات. إذا كنت تستورد تحديثات، فيمكنك الاحتفاظ بالمحتوى المنشور بالفعل كمنشور.','Return here, to %s, to set languages and connect translations'=>'عد إلى هنا، إلى %s، لتعيين اللغات وربط الترجمات','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'عند زيارة هذه الصفحة بعد استيراد المحتوى الذي يتضمن معلومات اللغة، ستتمكن من تشغيل %s لتطبيق اللغات وربط الترجمات.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'هل قمت بالاستيراد بالفعل وما زلت ترى هذه الشاشة؟ %1$sاستكشاف الأخطاء وإصلاحها %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'كيفية تصدير واستيراد المحتوى بلغات متعددة','%s is ready to update your imported content'=>'%s جاهز لتحديث محتواك المستورد','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'عمل جيد. نرى %1$d من العناصر و %2$d من المقالات التي تم استيرادها وتحتاج إلى معلومات اللغة.','Good job. We see %d terms that are imported and need language information.'=>'عمل جيد. نرى %d من العناصر التي تم استيرادها وتحتاج إلى معلومات اللغة.','Good job. We see %d posts that are imported and need language information.'=>'عمل جيد. نرى %d من المقالات التي تم استيرادها وتحتاج إلى معلومات اللغة.','Run WPML Import'=>'تشغيل WPML Import','Multilingual Import Complete'=>'اكتمل الاستيراد متعدد اللغات']];